import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Reuse and review runtime variables","description":"","frontmatter":{"title":"Reuse and review runtime variables","docId":"user.automations.variables","translationKey":"user.automations.variables","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","translationRevision":"afcdc4049fccbd2bc17c1040a9f84efb749a8d6291212cfe8809c22728e5c0fb","order":40},"headers":[],"relativePath":"en/user/automations/variables.md","filePath":"en/user/automations/variables.md","lastUpdated":1795727787000}`),s={name:`en/user/automations/variables.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="reuse-and-review-runtime-variables" tabindex="-1">Reuse and review runtime variables <a class="header-anchor" href="#reuse-and-review-runtime-variables" aria-label="Permalink to “Reuse and review runtime variables”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Change a shared value once and reuse it in several actions. You need <strong>Automations → Variables</strong> and a host that supports the relevant variable operations. Typed editing and reviewed Cloud operations appear according to host capabilities; local saving does not require uploading.</p><h2 id="save-a-local-value" tabindex="-1">Save a local value <a class="header-anchor" href="#save-a-local-value" aria-label="Permalink to “Save a local value”">​</a></h2><ol><li>Add a variable named <code>showLabel</code>. Keys start with a letter or underscore and may contain letters, digits, dots, underscores and hyphens, up to <code>64</code> characters. Avoid duplicate keys.</li><li>Where typed editing is available, choose text and enter <code>Evening show</code>. Other supported kinds are number, boolean, list and secret. Lists use a JSON array of strings, such as <code>[&quot;red&quot;, &quot;blue&quot;]</code>.</li><li>Select <strong>Save</strong>. A revision conflict means the saved collection changed; reload and review your intended edit against it.</li><li>Use the saved value in a templated action field:</li></ol><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{{ globals.showLabel }}: {{ event.user.uniqueId }}</span></span></code></pre></div><ol start="5"><li>Test a log-only action to inspect the rendered text. Change <code>showLabel</code>, save again and run a new test. Existing action definitions can reuse the updated value without re-importing a template.</li></ol><p>Template <code>params</code> are substituted when applying a template; <code>globals</code> are read at execution. A missing runtime key renders as empty text, so verify spelling before using it in a destination or identifier. Use the field&#39;s variable suggestions for event paths appropriate to its trigger.</p><p>Conditions can also publish per-match values. When a filter declares a capture alias, the value that satisfied it is available while the event&#39;s actions render as <code>{{ match.&lt;alias&gt; }}</code> (or <code>{{ match.&lt;position&gt; }}</code> when no alias is set). For example, a <code>starts with</code> condition on the comment with alias <code>prefix</code> lets a log action print <code>{{ match.prefix }}</code>. Captures are bounded plain text, are only produced by the filters and alternatives that actually matched, and do not change cooldown keys.</p><p>Press <strong>+</strong> beside a templated field to open <strong>Insert variable</strong>: the exact path appears on the right and choosing a row appends <code>{{ path }}</code> to the field. This event&#39;s capture paths are listed there too, but they resolve only when their condition actually matched. Give a condition an alias in the Conditions section (the <strong>Capture as</strong> button in the footer reveals the alias fields) to write <code>{{ match.&lt;alias&gt; }}</code>; otherwise use the positional <code>{{ match.&lt;position&gt; }}</code>.</p><h2 id="review-cloud-changes-separately" tabindex="-1">Review Cloud changes separately <a class="header-anchor" href="#review-cloud-changes-separately" aria-label="Permalink to “Review Cloud changes separately”">​</a></h2><p>The Variables <strong>Changes</strong> control has native reviewed send, fetch, apply/adopt and withdraw operations when supported. Save local edits first, select a comparison, inspect its type and value, and choose the intended direction explicitly. Fetching a Cloud candidate is separate from applying it locally. Withdrawing a shared value is separate from deleting a local row.</p><p>Secret or blocked values are masked in comparisons and cannot be sent through this reviewed path. Never turn a secret into ordinary text merely to bypass that block.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Expected result, status and recovery <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “Expected result, status and recovery”">​</a></h2><p>Local variables and capability-gated reviewed sharing are available; saving locally never uploads automatically. Invalid keys, invalid typed values and stale revisions block saving. Correct the highlighted field or reload before retrying. For account failures see <a href="./../cloud/account.html">Cloud account</a>; for comparison behavior see <a href="./../cloud/changes.html">Changes</a>.</p><p>Try it interactively before touching your real setup:</p>`,16),t(d,{scenario:`automation`,locale:`en`,panel:`automation`,title:`Try the automations workspace`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Command line operations <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Command line operations”">​</a></h2><p>Every operation in this guide is also available from the CLI — offline, scriptable and agent-friendly. Usage lines are parser syntax and stay in English in every locale.</p><table tabindex="0"><thead><tr><th>Command</th><th>Summary</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>list every global key</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>read one global</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>write one global</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>delete one global <strong>destructive</strong></td></tr></tbody></table><p>See the <a href="./../../developer/cli.html">full command reference</a> for conventions, JSON output and destructive-operation markers.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};